var builder = WebApplication.CreateSlimBuilder(args);

// Bind domain interfaces to infrastructure implementations
// Domain layer defines IOrderRepository, infrastructure provides EfOrderRepository
builder.Services.AddScoped<IOrderRepository, EfOrderRepository>();
builder.Services.AddScoped<IEmailSender, SmtpEmailSender>();
builder.Services.AddScoped<IEmbeddingService, AzureOpenAIEmbeddingService>();

// Register DB context (Infrastructure concern)
builder.Services.AddDbContext<AppDbContext>(options =>
    options.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection")));

// Health checks for all dependencies
builder.Services.AddHealthChecks()
    .AddDbContextCheck<AppDbContext>()
    .AddAzureOpenAI(OpenAIDeployment.Type.Embedding, "text-embedding-3-large")
    .AddRedis(builder.Configuration.GetConnectionString("Redis"));

var app = builder.Build();

// Middleware pipeline
app.MapControllers();
app.MapHealthChecks("/health");
app.Run();
